'use strict';
// Zero-dependency bundler for the SEA build: wraps the daemon modules in
// one CommonJS file with a tiny module registry. Native node:* modules
// pass through to the real require. require.main is emulated so
// server.js's self-start check triggers.

const fs = require('node:fs');
const path = require('node:path');

const HERE = __dirname;
const ROOT = path.join(HERE, '..');
const MODULES = ['prompts.js', 'db.js', 'engine.js', 'mcp.js', 'server.js'];
const srcPath = (name) => path.join(name === 'prompts.js' ? ROOT : HERE, name);

const headers = MODULES.map(name => {
  const src = fs.readFileSync(srcPath(name), 'utf8');
  return `registry["${name}"].src = ${JSON.stringify(src)};`;
}).join('\n');

const out = `'use strict';
// GENERATED by build-bundle.js — do not edit. Bundle for council-daemon.exe.
const nodeRequire = require;
const registry = {
${MODULES.map(n => `  "${n}": { src: null, exports: {}, loaded: false }`).join(',\n')}
};
${headers}

function loadModule(name) {
  const m = registry[name];
  if (m.loaded) return m.exports;
  m.loaded = true;
  const moduleObj = { exports: m.exports, filename: name, loaded: false };
  if (name === 'server.js') loadModule.main = moduleObj;
  const localRequire = (req) => {
    if (typeof req === 'string' && req.startsWith('node:')) return nodeRequire(req);
    const base = req.split('/').pop();
    const key = base.endsWith('.js') ? base : base + '.js';
    if (!registry[key]) throw new Error('bundle: module not found: ' + req);
    return loadModule(key);
  };
  localRequire.main = loadModule.main || null;
  const fn = new Function('exports', 'require', 'module', '__filename', '__dirname', m.src);
  fn(m.exports, localRequire, moduleObj, name, process.cwd());
  m.exports = moduleObj.exports; // modules may reassign module.exports
  return m.exports;
}

loadModule('server.js');
`;

const outPath = path.join(HERE, 'bundle.cjs');
fs.writeFileSync(outPath, out);
console.log('bundle written:', outPath, out.length, 'bytes');
